package org.apache.commons.lang;

import java.io.*;
import java.io.IOException;
import java.io.StringWriter;
import java.io.Writer;
import java.math.*;
import java.util.*;
import java.util.HashMap;
import java.util.Map;
import java.util.TreeMap;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

public class Entities_addEntities_TriageGen0Test {

    private Entities entities;

    @Before
    public void setUp() {
        // Since we are testing addEntities which calls addEntity, 
        // and addEntity is a method in the same class, we use a spy 
        // to verify the internal calls to addEntity.
        entities = spy(new Entities());
    }

    @Test
    public void testAddEntities_Success() {
        String[][] entityArray = {
            {"entity1", "10"},
            {"entity2", "20"},
            {"entity3", "30"}
        };

        entities.addEntities(entityArray);

        // Verify that addEntity was called with correct parameters for each element
        verify(entities).addEntity("entity1", 10);
        verify(entities).addEntity("entity2", 20);
        verify(entities).addEntity("entity3", 30);
        verify(entities, times(3)).addEntity(anyString(), anyInt());
    }

    @Test
    public void testAddEntities_EmptyArray() {
        String[][] entityArray = {};

        entities.addEntities(entityArray);

        // Should not call addEntity if array is empty
        verify(entities, never()).addEntity(anyString(), anyInt());
    }

    @Test(expected = NumberFormatException.class)
    public void testAddEntities_InvalidIntegerFormat() {
        String[][] entityArray = {
            {"entity1", "not_a_number"}
        };

        // This should trigger NumberFormatException during Integer.parseInt
        entities.addEntities(entityArray);
    }

    @Test(expected = ArrayIndexOutOfBoundsException.class)
    public void testAddEntities_MalformedInnerArray() {
        // Sub-array is missing the second element (index 1)
        String[][] entityArray = {
            {"entity1"}
        };

        entities.addEntities(entityArray);
    }

    @Test(expected = NullPointerException.class)
    public void testAddEntities_NullArray() {
        String[][] entityArray = null;

        // Should throw NullPointerException when accessing entityArray.length
        entities.addEntities(entityArray);
    }

    @Test(expected = NullPointerException.class)
    public void testAddEntities_NullElementInArray() {
        String[][] entityArray = {
            null
        };

        // Should throw NullPointerException when accessing entityArray[i][0]
        entities.addEntities(entityArray);
    }
}
